package xyz.toesinthesand.ashfall.director.client.special;

import net.minecraft.resources.Identifier;
import xyz.toesinthesand.ashfall.director.special.SpecialKind;

/**
 * How one special infected is drawn with no new model: the vanilla zombie model and texture, multiplied by a tint,
 * an overlay texture (generated by {@code tools/gen_entity_textures.py} from the vanilla zombie palette) drawn on
 * the same model, and a shape transform. The brute's size is not here: it is the {@code minecraft:scale}
 * attribute, which the vanilla renderer already applies.
 *
 * @param tint      ARGB multiplied into the vanilla zombie texture
 * @param overlay   texture drawn over the body (mostly transparent: pustules, acid, scars)
 * @param widthX    model width multiplier (x and z)
 * @param heightY   model height multiplier
 * @param leanDeg   forward lean around the feet, in degrees (the crawler's hunch)
 */
public record SpecialLook(int tint, Identifier overlay, float widthX, float heightY, float leanDeg) {
	public static SpecialLook of(SpecialKind kind) {
		Identifier overlay = Identifier.fromNamespaceAndPath("ashfall", "textures/entity/special/" + kind.id() + ".png");
		return switch (kind) {
			case CRAWLER -> new SpecialLook(0xFFC8D0B8, overlay, 1.0f, 0.8f, 55f);
			case BLOATED -> new SpecialLook(0xFFB8E890, overlay, 1.4f, 1.0f, 0f);
			case SCREAMER -> new SpecialLook(0xFFE4DCD4, overlay, 0.8f, 1.05f, 0f);
			case SPITTER -> new SpecialLook(0xFFD8E870, overlay, 1.0f, 1.0f, 8f);
			case BRUTE -> new SpecialLook(0xFFB09890, overlay, 1.0f, 1.0f, 0f);
			case STALKER -> new SpecialLook(0xFF707880, overlay, 0.9f, 1.02f, 0f);
		};
	}
}
